101	var (
102		defaultOnce           sync.Once
103		defaultInst           *Engine
104		defaultErr            error
105		defaultAttachmentOnce sync.Once
106		defaultAttachmentInst *Engine
107		defaultAttachmentErr  error
108	)
109	
110	// DefaultEngine returns the process-wide memo filter engine.
111	func DefaultEngine() (*Engine, error) {
112		defaultOnce.Do(func() {
113			defaultInst, defaultErr = NewEngine(NewSchema())
114		})
115		return defaultInst, defaultErr
116	}
117	
118	// DefaultAttachmentEngine returns the process-wide attachment filter engine.
119	func DefaultAttachmentEngine() (*Engine, error) {
120		defaultAttachmentOnce.Do(func() {
121			defaultAttachmentInst, defaultAttachmentErr = NewEngine(NewAttachmentSchema())
122		})
123		return defaultAttachmentInst, defaultAttachmentErr
124	}
