177	// accessorSpec maps a CEL timestamp accessor to per-dialect SQL date-part tokens
178	// and the offset to subtract so the result matches CEL's base (e.g. CEL months
179	// are 0-based but every dialect reports 1-based, so off=1). off is indexed
180	// [sqlite, postgres, mysql].
181	type accessorSpec struct {
182		sqlite string // strftime format specifier
183		pg     string // EXTRACT field
184		mysql  string // function name
185		off    [3]int
186	}
187	
188	var accessorSpecs = map[string]accessorSpec{
189		"getFullYear":   {"%Y", "YEAR", "YEAR", [3]int{0, 0, 0}},
190		"getMonth":      {"%m", "MONTH", "MONTH", [3]int{1, 1, 1}},
191		"getDate":       {"%d", "DAY", "DAYOFMONTH", [3]int{0, 0, 0}},
192		"getDayOfMonth": {"%d", "DAY", "DAYOFMONTH", [3]int{1, 1, 1}},
193		"getDayOfWeek":  {"%w", "DOW", "DAYOFWEEK", [3]int{0, 0, 1}},
194		"getDayOfYear":  {"%j", "DOY", "DAYOFYEAR", [3]int{1, 1, 1}},
195		"getHours":      {"%H", "HOUR", "HOUR", [3]int{0, 0, 0}},
196		"getMinutes":    {"%M", "MINUTE", "MINUTE", [3]int{0, 0, 0}},
197		"getSeconds":    {"%S", "SECOND", "SECOND", [3]int{0, 0, 0}},
198	}
199	
200	func (r *renderer) renderAccessorComparison(acc *FieldAccessorValue, op ComparisonOperator, right ValueExpr) (renderResult, error) {
201		field, ok := r.schema.Field(acc.Field)
202		if !ok {
203			return renderResult{}, errors.Errorf("unknown field %q", acc.Field)
204		}
205		value, err := expectNumericLiteral(right)
206		if err != nil {
207			return renderResult{}, err
208		}
209		expr, err := r.timestampAccessorExpr(field, acc.Accessor)
210		if err != nil {
211			return renderResult{}, err
212		}
213		placeholder := r.addArg(value)
214		return renderResult{
215			sql: fmt.Sprintf("%s %s %s", expr, sqlOperator(op), placeholder),
216		}, nil
217	}
218	
219	// timestampAccessorExpr builds a dialect-specific integer expression for a CEL
220	// timestamp accessor. Extraction is UTC on SQLite/Postgres (epoch columns); on
221	// MySQL the TIMESTAMP column is read in the server session time zone.
222	func (r *renderer) timestampAccessorExpr(field Field, accessor string) (string, error) {
223		spec, ok := accessorSpecs[accessor]
224		if !ok {
225			return "", errors.Errorf("unsupported timestamp accessor %q", accessor)
226		}
227		col := qualifyColumn(r.dialect, field.Column)
228		var base string
229		var off int
230		switch r.dialect {
231		case DialectSQLite:
232			base = fmt.Sprintf("CAST(strftime('%s', %s, 'unixepoch') AS INTEGER)", spec.sqlite, col)
233			off = spec.off[0]
234		case DialectPostgres:
235			base = fmt.Sprintf("CAST(EXTRACT(%s FROM to_timestamp(%s) AT TIME ZONE 'UTC') AS INTEGER)", spec.pg, col)
236			off = spec.off[1]
237		case DialectMySQL:
238			base = fmt.Sprintf("%s(%s)", spec.mysql, col)
239			off = spec.off[2]
240		default:
241			return "", errors.Errorf("unsupported dialect %q", r.dialect)
242		}
243		if off != 0 {
244			base = fmt.Sprintf("(%s - %d)", base, off)
245		}
246		return base, nil
247	}
